const params = {};
if ($.input.teamId) params.teamId = $.input.teamId;
return { params };

const resp = $.steps.getEnvVars.response || {};
const envs = (resp.envs || resp || []);
const vars = (Array.isArray(envs) ? envs : []).map(e => ({
  key: e.key || '',
  value: e.value ? '***' : '',
  target: e.target || [],
  type: e.type || '',
  id: e.id || ''
}));

return {
  variables: vars,
  totalVars: vars.length,
  summary: `Found ${vars.length} environment variable${vars.length === 1 ? '' : 's'} for project "${$.input.projectId}"`
};
